from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.adjustments import outage_refund
from ledgerly.models import Payment
from ledgerly.errors import BillingError
T0=datetime(2026,10,1,tzinfo=timezone.utc)
def mk(status="captured",amt="80.00"):
    return Payment("p","i",Decimal(amt),status=status,created_at=T0,captured_at=T0)

# partial then full
p=mk(); outage_refund(p,Decimal("8.00"),T0); print(p.refunded_amount,p.status)
outage_refund(p,Decimal("72.00"),T0); print(p.refunded_amount,p.status)
# over refund
p=mk()
try: outage_refund(p,Decimal("80.01"),T0)
except BillingError as e: print("over:",e.code)
# non-captured
for st in ("authorized","voided","refunded"):
    try: outage_refund(mk(st),Decimal("1.00"),T0)
    except BillingError as e: print(st,"->",e.code)
# non-positive
for a in ("0","-1"):
    try: outage_refund(mk(),Decimal(a),T0)
    except BillingError as e: print(a,"->",e.code)
# banker's rounding 0.125 -> 0.12
p=mk(); outage_refund(p,Decimal("0.125"),T0); print("round:",p.refunded_amount)
# naive datetime
try: outage_refund(mk(),Decimal("1"),datetime(2026,10,1))
except BillingError as e: print("naive:",e.code)
EOF"}

